import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import base64
from io import BytesIO
import datetime

# Setup matplotlib for headless
plt.switch_backend('Agg')

def encode_fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    image_base64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return image_base64

# Load data
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')
print("Data loaded.")

df['order_date'] = pd.to_datetime(df['order_date'])
df['year_month'] = df['order_date'].dt.to_period('M')

# KPIs
total_revenue = df['revenue'].sum()
total_profit = df['profit'].sum()
# "Mean ratio of profit to revenue, expressed as a percentage."
df['margin_ratio'] = df['profit'] / df['revenue']
avg_profit_margin = df['margin_ratio'].mean() * 100
aov = df.groupby('order_id')['revenue'].sum().mean()
discount_utilization = (df['discount'] > 0).mean() * 100

print("Generating Chart 1...")
# Chart 1: Sales Trends Over Time
monthly_sales = df.groupby('year_month').agg({'revenue': 'sum', 'order_id': 'nunique'}).reset_index()
monthly_sales['year_month_str'] = monthly_sales['year_month'].dt.strftime('%Y-%m')

fig, ax1 = plt.subplots(figsize=(12, 6))
ax1.set_title('Sales Trends Over Time', fontsize=16, pad=20)
color = '#2980b9'
ax1.set_xlabel('Month', fontsize=12)
ax1.set_ylabel('Revenue ($)', color=color, fontsize=12)
ax1.plot(monthly_sales['year_month_str'], monthly_sales['revenue'], color=color, marker='o', linewidth=2, label='Revenue')
ax1.tick_params(axis='y', labelcolor=color)
plt.xticks(rotation=45)
ax1.grid(True, linestyle='--', alpha=0.6)

ax2 = ax1.twinx()
color = '#e67e22'
ax2.set_ylabel('Order Volume', color=color, fontsize=12)
ax2.plot(monthly_sales['year_month_str'], monthly_sales['order_id'], color=color, marker='s', linestyle='--', linewidth=2, label='Orders')
ax2.tick_params(axis='y', labelcolor=color)

fig.legend(loc="upper left", bbox_to_anchor=(0.1,0.9))
fig.tight_layout()
sales_trend_img = encode_fig_to_base64(fig)

print("Generating Chart 2...")
# Chart 2: Discount Impact
discount_analysis = df.groupby('discount').agg({
    'revenue': 'sum',
    'margin_ratio': 'mean',
    'quantity': 'mean'
}).reset_index()
discount_analysis['margin_pct'] = discount_analysis['margin_ratio'] * 100
discount_analysis['discount_str'] = (discount_analysis['discount'] * 100).astype(int).astype(str) + '%'

fig, ax1 = plt.subplots(figsize=(10, 5))
ax1.set_title('Discount Impact & Profitability Analysis', fontsize=16, pad=20)
color = '#27ae60'
ax1.set_xlabel('Discount Level', fontsize=12)
ax1.set_ylabel('Avg Profit Margin (%)', color=color, fontsize=12)
bars = ax1.bar(discount_analysis['discount_str'], discount_analysis['margin_pct'], color=color, alpha=0.7, width=0.5)
ax1.tick_params(axis='y', labelcolor=color)
ax1.grid(axis='y', linestyle='--', alpha=0.6)

# Add data labels to bars
for bar in bars:
    yval = bar.get_height()
    ax1.text(bar.get_x() + bar.get_width()/2, yval + 1, f'{yval:.1f}%', ha='center', va='bottom', fontsize=10)

ax2 = ax1.twinx()
color = '#c0392b'
ax2.set_ylabel('Avg Quantity per Transaction', color=color, fontsize=12)
ax2.plot(discount_analysis['discount_str'], discount_analysis['quantity'], color=color, marker='o', linewidth=2, label='Quantity')
ax2.tick_params(axis='y', labelcolor=color)

fig.tight_layout()
discount_img = encode_fig_to_base64(fig)

print("Formatting Tables...")
# Product Analysis (Top 10)
top_products = df.groupby('product_id').agg({'revenue': 'sum', 'profit': 'sum'}).sort_values('revenue', ascending=False).head(10).reset_index()
top_products.columns = ['Product ID', 'Total Revenue ($)', 'Total Profit ($)']
products_html = top_products.to_html(classes="table table-striped", index=False, float_format="{:,.2f}".format)

# Store Analysis (Top 10)
top_stores = df.groupby('store_id').agg({'revenue': 'sum', 'profit': 'sum'}).sort_values('revenue', ascending=False).head(10).reset_index()
top_stores.columns = ['Store ID', 'Total Revenue ($)', 'Total Profit ($)']
stores_html = top_stores.to_html(classes="table table-striped", index=False, float_format="{:,.2f}".format)

