        }}
        h1 {{ margin: 0; font-size: 2.5rem; font-weight: 600; }}
        header p {{ margin: 10px 0 0; font-size: 1.2rem; opacity: 0.9; }}
        h2 {{
            color: var(--primary-color);
            border-bottom: 2px solid var(--accent-color);
            padding-bottom: 10px;
            margin-top: 50px;
            font-weight: 500;
        }}
        h3 {{ color: var(--secondary-color); font-weight: 500; }}

        .kpi-container {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin-top: 30px;
        }}
        .kpi-card {{
            background: #fff;
            border-radius: 10px;
            box-shadow: 0 4px 15px rgba(0,0,0,0.05);
            padding: 25px 20px;
            text-align: center;
            border-top: 4px solid var(--accent-color);
            transition: transform 0.2s;
        }}
        .kpi-card:hover {{ transform: translateY(-5px); }}
        .kpi-value {{
            font-size: 2rem;
            font-weight: 700;
            color: var(--primary-color);
            margin: 15px 0 5px;
        }}
