        }}
    </style>
</head>
<body>
    <header>
        <h1>Chocolate Retail Sales Performance</h1>
        <p>2023–2024 Management Dashboard</p>
    </header>

    <div class="container">
        <!-- Executive Summary -->
        <div class="section" id="executive-summary">
